import React from "react";

export default function  Passions(){
    const passionItems=[
        {
            id:0,
            title:"Front-End development",
            subTitle:"React,NextJs,Angular,Flutter"
        },
        {
            id:1,
            title:"Back-End developement",
            subTitle:"NodeJS,Express,MongoDb,Python"
        },
        {
            id:2,
            title:"UI/UX",
            subTitle:"Figma, Adobe XD"
        }
    ]
    return(
        <div className="flex flex-col w-[100%]">
            <div>MY SKILLS</div>
            <div className="flex flex-col w-[100%] items-center justify-center">
                <div className="flex w-fit flex-row p-2 items-center border rounded-[20px] justify-center gap-3">
                    {passionItems.map((item,index)=>(
                        <div key={index}>
                            {item.title}
                            {index+1 !== passionItems.length &&
                                <span> | </span>
                            }
                        </div>
                    ))}
                </div>
                {passionItems.map((item,index)=>(
                    <div className="flex flex-col w-[40%] ml-4 rounded-[20px]" key={index}>
                        <div className="text-2xl">{item.title}</div>
                        <div className="text-large">{item.subTitle}</div>
                    </div>
                ))}
            </div>
        </div>
    )
}
